'use strict';
// Optional extension: legacy archives keep their identity and migrate without writes.
const OPS_TABLES=['opsRecords','opsCalculations','opsTrash','opsHistory','opsVersions'];
const OPS_KINDS={
 access:{title:'Достъп и условия',client:true,fields:[['contact','Контакт на място'],['parking','Паркиране и достъп'],['water','Вода и електрозахранване'],['hours','Разрешени часове'],['pets','Домашни животни / особености']]},
 issue:{title:'Проблем и контрол',client:true,fields:[['location','Място / растение'],['observation','Наблюдение','textarea'],['action','Предприета мярка','textarea'],['due','Повторна проверка','date']]},
 product:{title:'Вложен продукт',client:true,fields:[['product','Продукт от етикета'],['quantity','Вложено количество','number'],['unit','Мерна единица'],['area','Обработена площ m²','number'],['rate','Норма от етикета (текст)'],['weather','Условия при работа'],['due','Следваща проверка','date']]},
 extra:{title:'Допълнително възлагане',client:true,fields:[['scope','Допълнителна работа','textarea'],['amount','Уговорена цена €','number'],['approval','Как и от кого е потвърдено'],['due','Срок','date']]},
 acceptance:{title:'Приемане на работа',client:true,fields:[['completed','Изпълнено','textarea'],['remarks','Забележки / оставащо','textarea'],['approval','Представител и начин на потвърждение'],['due','Срок за оставащото','date']]},
 rental:{title:'Наем и връщане',fields:[['supplier','Наемодател'],['equipmentId','Машина от инвентара','equipment'],['amount','Уговорен наем €','number'],['deposit','Депозит €','number'],['due','Връщане до','date'],['returned','Върнато / остатъчни материали','textarea']]},
 warranty:{title:'Гаранционен ангажимент',client:true,fields:[['scope','Обхват и условия','textarea'],['exclusions','Изключения / грижи от клиента','textarea'],['due','Гаранция до','date'],['checkDate','Контролно посещение','date']]},
 lead:{title:'Потенциален клиент',fields:[['contact','Име / телефон'],['location','Населено място'],['source','Откъде е дошла заявката'],['scope','Търсена работа','textarea'],['due','Следващ контакт','date']]},
 renewal:{title:'Подновяване на договор',client:true,fields:[['documentId','Свързан договор / оферта','document'],['amount','Предложена нова цена €','number'],['basis','Период на цената'],['due','Обсъждане до','date'],['scope','Промени в обхвата','textarea']]},
 supplier:{title:'Сравнение на доставчик',fields:[['product','Артикул'],['supplier','Доставчик'],['quantity','Количество в разфасовка','number'],['unit','Еднаква базова единица (kg, l, бр.)'],['amount','Цена на разфасовката €','number'],['delivery','Доставка €','number'],['url','Линк към продукта','url'],['due','Валидност на цената','date']]},
 stage:{title:'Етапно плащане',client:true,fields:[['amount','Дължима сума за етапа €','number'],['paymentId','Вече записано плащане','payment'],['due','Падеж','date']]},
 maintenance:{title:'Напомняне за сервиз',fields:[['equipmentId','Машина','equipment'],['meter','Обслужване при общи моточасове','number'],['due','Обслужване до','date'],['scope','Какво да се обслужи','textarea']]},
 return:{title:'Остатъчни материали',fields:[['product','Материал / инструмент'],['quantity','Количество','number'],['unit','Мерна единица'],['location','Къде се намира'],['due','Връщане / проверка до','date']]},
 map:{title:'Схема на обект',client:true,fields:[['markers','Точки: име | X % | Y % — по една на ред','textarea'],['scope','Легенда и уточнения','textarea']]},
 idea:{title:'Сезонно предложение',client:true,fields:[['scope','Идея и полза за обекта','textarea'],['season','Сезон / месец'],['amount','Ориентировъчна цена €','number'],['due','Обсъждане до','date']]}
};
const OPS_STATUSES=['Чернова','За уточняване','Планирано','Чака одобрение','Одобрено','В работа','Приключено','Отказано'];
const opsRows=(data=db)=>data.opsRecords||[];
const opsText=(x,n=15000)=>typeof x==='string'&&x.length<=n;
function opsNumber(x,required=false,max=1e8){if(x===''||x===null||x===undefined){if(required)throw Error('Попълни необходимото число.');return null}const n=typeof x==='number'?x:Number(String(x).replace(',','.'));if(!Number.isFinite(n)||n<0||n>max)throw Error('Невалидно число. Използвай положителна стойност и правилната мерна единица.');return n}
function opsDate(x,optional=true){return (!x&&optional)||typeof x==='string'&&/^\d{4}-(0[1-9]|1[0-2])-([0-2]\d|3[01])$/.test(x)&&new Date(x+'T12:00:00').toISOString().slice(0,10)===x}
function opsPayment(id,data=db){return [...data.payments,...data.subscriptionPayments].find(p=>p.id===id)}
function opsPaidClient(p,data=db){return p.clientId||data.visits.find(v=>v.id===p.visitId)?.clientId||''}
function opsValidate(data){
 for(const d of data.documents)if(d.opsFollowup&&!opsDate(d.opsFollowup))throw Error('Невалидна дата за следващ контакт.');
 const n=v=>v===null||typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=1e8,usedPayments=new Set;
 for(const r of opsRows(data)){
  const def=OPS_KINDS[r.kind];if(!def||!opsText(r.title,500)||!r.title.trim()||!opsDate(r.date,false)||!OPS_STATUSES.includes(r.status)||!opsText(r.notes||''))throw Error('Невалиден запис в работния център.');
  if(def.client&&!data.clients.some(c=>c.id===r.clientId))throw Error('Избери клиент за записа.');
  if(r.clientId&&!data.clients.some(c=>c.id===r.clientId))throw Error('Липсва клиент.');
  const visit=data.visits.find(v=>v.id===r.visitId);if(r.visitId&&(!visit||visit.clientId!==r.clientId))throw Error('Посещението трябва да е за същия клиент.');
  if(r.equipmentId&&!data.equipment.some(e=>e.id===r.equipmentId))throw Error('Липсва свързаната машина.');
  if(r.kind==='supplier'&&r.quantity!==null&&(!r.unit||!r.product||!r.supplier))throw Error('За сравнение попълни артикул, доставчик и базова единица.');
  if(r.paymentId&&r.kind!=='stage')throw Error('Плащане се свързва само с етап.');
  if(r.documentId&&!data.documents.some(d=>d.id===r.documentId&&d.clientId===r.clientId))throw Error('Документът трябва да е за същия клиент.');
  for(const [k,,t]of def.fields){const v=r[k];if(t==='number'&&!n(v))throw Error('Невалидна числова стойност.');if(t==='date'&&!opsDate(v))throw Error('Невалидна дата.');if(!['number','date'].includes(t)&&!opsText(v||''))throw Error('Невалидно текстово поле.');}
  if(r.photo&&!/^data:image\/(jpeg|png|webp);base64,/.test(r.photo))throw Error('Невалидна снимка.');
  if(r.kind==='supplier'&&(r.quantity!==null&&r.quantity<=0))throw Error('Разфасовката трябва да е над нула.');
  if(r.url&&!/^https?:\/\//i.test(r.url))throw Error('Линкът трябва да започва с https:// или http://.');
  if(r.kind==='maintenance'&&!r.equipmentId)throw Error('Избери машина за обслужването.');
  if(r.kind==='stage'&&r.paymentId){const p=opsPayment(r.paymentId,data);if(!p||opsPaidClient(p,data)!==r.clientId||usedPayments.has(p.id))throw Error('Плащането липсва, е за друг клиент или вече покрива друг етап.');if(r.amount===null||p.amount>r.amount+.005)throw Error('Свържи плащане до сумата на етапа. За по-голямо плащане уточни етапите.');if(r.visitId&&p.visitId!==r.visitId)throw Error('Плащането е към друго посещение.');usedPayments.add(p.id);}
  if(r.kind==='map')opsMarkers(r.markers||'');
 }
 for(const c of data.opsCalculations||[]){if(!opsText(c.title,500)||!c.title.trim()||!data.clients.some(x=>x.id===c.clientId)||!opsDate(c.date,false)||!['Чернова','Одобрена','Приключена'].includes(c.status)||!Array.isArray(c.lines)||c.lines.length>100||!n(c.margin)||c.margin===null||c.margin>=100)throw Error('Невалидна калкулация.');for(const l of c.lines)if(!opsText(l.name,500)||!l.name.trim()||!opsText(l.unit,30)||!l.unit.trim()||!n(l.qty)||l.qty===null||l.qty<=0||!n(l.cost)||typeof l.included!=='boolean'||typeof l.optional!=='boolean')throw Error('Невалидна позиция в калкулацията.');for(const k of ['laborHours','laborRate','transport','rental','other'])if(!n(c[k]))throw Error('Невалиден разход в калкулацията.');if(c.purchaseIds&&(!Array.isArray(c.purchaseIds)||c.purchaseIds.some(id=>!data.purchases.some(p=>p.id===id&&p.clientId===c.clientId))))throw Error('Липсва свързана покупка.');if(c.documentId&&!data.documents.some(d=>d.id===c.documentId&&d.clientId===c.clientId))throw Error('Липсва свързана оферта.');}
 for(const t of data.opsTrash||[])if(!Array.isArray(t.items)||!t.items.length||t.items.length>50000||t.items.some(i=>!TABLES.includes(i.table)||OPS_TABLES.slice(2).includes(i.table)||!i.record||typeof i.record.id!=='string'))throw Error('Невалидно кошче.');
 for(const v of data.opsVersions||[])if(!v.record||typeof v.record.id!=='string'||v.table!=='documents')throw Error('Невалидна версия на документ.');
 if(data.settings.opsSchedule){const s=data.settings.opsSchedule;if(!opsDate(s.anchor,false)||!Array.isArray(s.a)||!Array.isArray(s.b)||s.a.length!==7||s.b.length!==7||[...s.a,...s.b].some(h=>typeof h!=='number'||h<0||h>24)||!n(s.travel)||s.travel===null||!n(s.defaultHours)||s.defaultHours===null)throw Error('Невалиден график на свободното време.');}
 if(data.settings.opsTimer){const t=data.settings.opsTimer;if(!data.visits.some(v=>v.id===t.visitId)||!Number.isFinite(t.elapsed)||t.elapsed<0||t.elapsed>604800000||t.started!==null&&(!Number.isFinite(t.started)||t.started<=0))throw Error('Невалиден работен таймер.');}
}
function opsMarkers(text){if(!text.trim())return [];const rows=text.trim().split('\n');if(rows.length>50)throw Error('До 50 точки в една схема.');return rows.map(line=>{const [label,x,y,...extra]=line.split('|').map(s=>s.trim());const nx=opsNumber(x,true,100),ny=opsNumber(y,true,100);if(!label||extra.length)throw Error('Точка: име | X от 0 до 100 | Y от 0 до 100.');return {label,x:nx,y:ny}})}
let opsSkipCapture=false;
function opsConcurrentGuard(before){const raw=localStorage.getItem(KEY);if(!raw)return;const persisted=JSON.parse(raw);if((persisted.settings?.mutationCounter||0)>(before.settings?.mutationCounter||0))throw Error('Има по-нова промяна от друг прозорец. Презареди приложението преди нов запис.');}
function opsCapture(before,after){
 if(opsSkipCapture)return;const removed=[],edits=[],versions=[];for(const table of TABLES.filter(t=>!['opsTrash','opsHistory','opsVersions'].includes(t))){const old=new Map((before[table]||[]).map(r=>[r.id,r])),now=new Map((after[table]||[]).map(r=>[r.id,r]));for(const [id,r]of old){if(!now.has(id)){removed.push({table,record:r});edits.push('Премахнат: '+opsLabel(table,r));}else if(JSON.stringify(r)!==JSON.stringify(now.get(id))){edits.push('Променен: '+opsLabel(table,r));if(table==='documents')versions.push({id:uid(),table,record:{...r,clientSnapshot:r.clientSnapshot||structuredClone(before.clients.find(c=>c.id===r.clientId)||{}),companySnapshot:r.companySnapshot||structuredClone(before.settings)},date:today(),savedAt:new Date().toISOString()});}}for(const [id,r]of now)if(!old.has(id))edits.push('Добавен: '+opsLabel(table,r));}
 after.opsTrash||=[];after.opsHistory||=[];after.opsVersions||=[];
 if(removed.length)after.opsTrash.push({id:uid(),date:today(),savedAt:new Date().toISOString(),items:removed});
 after.opsVersions.push(...versions); // No automatic purging: snapshots may be needed for old offers.
 if(edits.length)after.opsHistory.push({id:uid(),date:today(),time:new Date().toISOString(),summary:edits.slice(0,100).join('\n')});
 if(after.opsHistory.length>300)after.opsHistory.splice(0,after.opsHistory.length-300);
}
function opsLabel(table,r){return (titles[table]||managerLabels?.[table]||OPS_KINDS[r.kind]?.title||table)+': '+(r.title||r.name||r.description||r.number||r.service||r.id).slice(0,180)}
function opsRestore(id){const t=db.opsTrash.find(t=>t.id===id);if(!t)throw Error('Записът в кошчето липсва.');return change(()=>{for(const i of t.items){if(TABLES.some(k=>db[k].some(r=>r.id===i.record.id)))throw Error('Идентификаторът вече се използва.');db[i.table].push(structuredClone(i.record));}db.opsTrash=db.opsTrash.filter(x=>x.id!==id);validate(db);})}
function opsBeforeDelete(table,id){const refs={clients:'clientId',visits:'visitId',equipment:'equipmentId',documents:'documentId',payments:'paymentId',subscriptionPayments:'paymentId'};if(refs[table]&&opsRows().some(r=>r[refs[table]]===id))return 'Записът има връзка в Работния център. Първо редактирай или премахни свързания запис.';if(table==='visits'&&db.settings.opsTimer?.visitId===id)return 'Първо приключи таймера на посещението.';if(table==='documents'&&db.opsCalculations?.some(c=>c.documentId===id)||table==='purchases'&&db.opsCalculations?.some(c=>c.purchaseIds?.includes(id)))return 'Записът е свързан с калкулация. Първо премахни връзката от нея.';return ''}
function opsCalc(c){const selected=c.lines.filter(l=>l.included),unknown=selected.some(l=>l.cost===null)||['laborHours','laborRate','transport','rental','other'].some(k=>c[k]===null),materials=sum(selected,l=>l.qty*(l.cost||0)),labor=cents((c.laborHours||0)*(c.laborRate||0))/100,cost=(cents(materials)+cents(labor)+cents(c.transport)+cents(c.rental)+cents(c.other))/100,price=Math.round(cents(cost)/(1-c.margin/100))/100;return {materials,labor,cost,price,profit:(cents(price)-cents(cost))/100,unknown}}
function opsMaterial(area,mode,value,waste=0){area=opsNumber(area,true);value=opsNumber(value,true);waste=opsNumber(waste,true,100);return area*value*(mode==='layer'?.01:.001)*(1+waste/100)}
function opsSupplierUnit(r){return r.quantity>0&&r.amount!==null?{withoutDelivery:r.amount/r.quantity,withDelivery:r.delivery===null?null:(r.amount+r.delivery)/r.quantity}:null}
function opsStageBalance(r){return r.amount===null?null:Math.max(0,(cents(r.amount)-cents(opsPayment(r.paymentId)?.amount))/100)}
function opsTimerElapsed(t=db.settings.opsTimer,now=Date.now()){return t?Math.max(0,t.elapsed+(t.started?now-t.started:0)):0}
function opsTimer(action,visitId){const v=db.visits.find(v=>v.id===visitId);if(!v)throw Error('Посещението липсва.');return change(()=>{let t=db.settings.opsTimer;if(action==='start'){if(v.status==='Отменено')throw Error('Посещението е отменено.');if(t&&t.visitId!==visitId)throw Error('Приключи таймера на другото посещение.');if(t?.started)return;db.settings.opsTimer=t?{...t,started:Date.now()}:{visitId,elapsed:0,started:Date.now()};}else{if(!t||t.visitId!==visitId)throw Error('Няма таймер за посещението.');const elapsed=opsTimerElapsed(t);if(elapsed>604800000)throw Error('Таймерът е над 168 часа. Коригирай часовете в посещението и отмени таймера.');if(action==='pause')db.settings.opsTimer={visitId,elapsed,started:null};if(action==='finish'){const hours=Math.round((visitHours(v)+elapsed/3600000)*1000)/1000;if(hours>168)throw Error('Общото време е над 168 часа. Провери продължителността.');v.durationHours=hours;delete db.settings.opsTimer;}if(action==='cancel')delete db.settings.opsTimer;}})}
function opsCapacity(day,s=db.settings.opsSchedule){if(!s)return null;const d=new Date(day+'T12:00:00'),a=new Date(s.anchor+'T12:00:00'),days=Math.round((d-a)/86400000),week=((Math.floor(days/7)%2)+2)%2;return (week?s.b:s.a)[(d.getDay()+6)%7]}
function opsWorkload(day){const rows=db.visits.filter(v=>v.date===day&&v.status!=='Отменено'),s=db.settings.opsSchedule,work=rows.reduce((a,v)=>a+(visitHours(v)||s?.defaultHours||0),0),travel=s?rows.length*s.travel:0;return {rows,work,travel,total:work+travel,capacity:opsCapacity(day),unknown:rows.some(v=>!visitHours(v))}}
function opsReschedule(ids,target){if(!opsDate(target,false)||!ids.length)throw Error('Избери посещения и валидна дата.');return change(()=>{const rows=ids.map(id=>db.visits.find(v=>v.id===id));if(rows.some(v=>!v||v.status!=='Планирано'||db.settings.opsTimer?.visitId===v.id))throw Error('Преместват се само планирани посещения без активен таймер.');for(const v of rows){const old={...v};v.date=target;syncInspectionFromVisit(v,old);} })}
function opsClientOptions(value='',emptyLabel='Без избран клиент'){return `<option value="">${emptyLabel}</option>`+db.clients.map(c=>`<option value="${esc(c.id)}" ${c.id===value?'selected':''}>${esc(c.name)}</option>`).join('')}
function opsSelect(name,label,value,options,required=false){return `<label class="field">${esc(label)}<select name="${name}" ${required?'required':''}><option value="">Избери…</option>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`}
function opsField(name,label,value='',type='text',required=false){if(type==='textarea')return `<label class="field full">${esc(label)}<textarea name="${name}" maxlength="15000" ${required?'required':''}>${esc(value)}</textarea></label>`;return `<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value??'')}" ${required?'required':''} ${type==='number'?'min="0" max="100000000" step="any"':'maxlength="500"'}></label>`}
function opsDialog(title,html){if($('#modal')?.open)wpReplaceDialog(()=>modal(title,html));else modal(title,html)}
function opsForm(kind,id='',pref={}){const def=OPS_KINDS[kind];if(!def)throw Error('Неизвестен вид запис.');const r=opsRows().find(r=>r.id===id)||{title:def.title,date:today(),status:'Чернова',clientId:state.opsClient||'',...pref};const opts=(t)=>t==='equipment'?db.equipment.map(e=>[e.id,e.name]):t==='document'?db.documents.filter(d=>d.clientId===r.clientId).map(d=>[d.id,d.type+' № '+d.number]):[...db.payments,...db.subscriptionPayments].filter(p=>opsPaidClient(p)===r.clientId).map(p=>[p.id,date(p.date)+' · '+money(p.amount)]);
 opsDialog(def.title,`<form id="ops-record-form" data-kind="${kind}" data-id="${esc(id)}"><div class="form-grid">${opsField('title','Заглавие',r.title,'text',true)}<label class="field">Клиент / обект<select name="clientId" ${def.client?'required':''}>${opsClientOptions(r.clientId)}</select></label>${opsField('date','Дата',r.date,'date',true)}${opsSelect('status','Състояние',r.status,OPS_STATUSES,true)}${opsSelect('visitId','Посещение (по избор)',r.visitId,db.visits.filter(v=>v.clientId===r.clientId).map(v=>[v.id,date(v.date)+' · '+v.service]))}${def.fields.map(([k,l,t='text'])=>['equipment','document','payment'].includes(t)?opsSelect(k,l,r[k],opts(t)):opsField(k,l,r[k],t)).join('')}${opsField('notes','Вътрешни бележки',r.notes,'textarea')}<label class="field full">Снимка / етикет / скица<input type="file" name="photo" accept="image/*"></label>${r.photo?`<img class="ops-thumb" src="${esc(r.photo)}" alt="Запазена снимка"><label><input type="checkbox" name="removePhoto"> Премахни снимката</label>`:''}</div><p class="muted">Празното число означава „неуточнено“. Записът не създава автоматично разход, плащане или посещение.${kind==='stage'?' Свържи вече отчетено плащане. За частични плащания използвай отделни подетапи.':''}${kind==='product'?' Нормата и мерките се проверяват по етикета; не се предлагат автоматични дозировки.':''}</p><div id="form-error" class="error" hidden></div><div class="actions"><button type="submit" class="primary">Запази</button>${id?btn('Към кошчето','ops-delete','trash','danger',`data-table="opsRecords" data-id="${esc(id)}"`):''}</div></form>`)
}
function opsRow(r){const unit=r.kind==='supplier'?opsSupplierUnit(r):null;return `<section class="card"><div class="row between"><div><strong>${esc(r.title)}</strong><small>${esc(OPS_KINDS[r.kind].title)} · ${esc(cname(r.clientId))} · ${date(r.date)}</small></div>${badge(r.status)}</div>${r.due?`<p class="${r.due<today()&&!['Приключено','Отказано'].includes(r.status)?'error':'muted'}">Срок: ${date(r.due)}</p>`:''}${r.kind==='stage'?`<p>Етап: ${r.amount===null?'неуточнен':money(r.amount)} · Свързано плащане: ${money(opsPayment(r.paymentId)?.amount)} · Остатък: ${opsStageBalance(r)===null?'—':money(opsStageBalance(r))}</p>`:''}${unit?`<p>Единична цена: ${money(unit.withoutDelivery)}/${esc(r.unit)} · с доставка: ${unit.withDelivery===null?'неуточнена':money(unit.withDelivery)+'/'+esc(r.unit)}</p>`:''}${r.kind==='map'&&r.photo?opsMap(r):r.photo?`<img class="ops-thumb" src="${esc(r.photo)}" alt="Снимка към записа">`:''}<div class="actions">${btn('Преглед / редакция','ops-edit','edit','secondary',`data-id="${esc(r.id)}"`)}${btn('Проверка / задача','ops-task','calendar','secondary',`data-id="${esc(r.id)}"`)}${['extra','acceptance','warranty','idea'].includes(r.kind)?btn('Клиентски PDF','ops-pdf','download','secondary',`data-id="${esc(r.id)}"`):''}</div></section>`}
function opsMap(r){return `<div class="ops-map"><img src="${esc(r.photo)}" alt="Схема на обекта">${opsMarkers(r.markers||'').map((m,i)=>`<span style="left:${m.x}%;top:${m.y}%" title="${esc(m.label)}">${i+1}</span>`).join('')}</div><p>${opsMarkers(r.markers||'').map((m,i)=>`${i+1}. ${esc(m.label)}`).join(' · ')}</p>`}
function opsPublicText(r){const allowed={extra:['scope','amount','approval','due'],acceptance:['completed','remarks','approval','due'],warranty:['scope','exclusions','due','checkDate'],idea:['scope','season','amount','due']};if(!allowed[r.kind])throw Error('Този запис е само за вътрешна употреба.');return [r.title,'Обект: '+cname(r.clientId),'Дата: '+date(r.date),'Състояние: '+r.status,...OPS_KINDS[r.kind].fields.filter(([k])=>allowed[r.kind].includes(k)).filter(([k])=>r[k]!==null&&r[k]!==undefined&&r[k]!=='').map(([k,l,t])=>l+': '+(t==='date'?date(r[k]):k==='amount'?money(r[k]):r[k])),'Потвърждението е въведен запис; не удостоверява самостоятелно електронен подпис.'].join('\n\n')}
function opsHub(){const k=state.opsKind||'',cl=state.opsClient||'',rows=opsRows().filter(r=>(!k||r.kind===k)&&(!cl||r.clientId===cl)).sort((a,b)=>(a.due||a.date).localeCompare(b.due||b.date));return `<div class="card"><h2>Работен център</h2><p>Уговорки, проблеми, гаранции и следващи действия към обекта.</p><div class="form-grid"><label class="field">Вид<select id="ops-kind"><option value="">Всички</option>${Object.entries(OPS_KINDS).map(([v,d])=>`<option value="${v}" ${v===k?'selected':''}>${d.title}</option>`).join('')}</select></label><label class="field">Клиент<select id="ops-client">${opsClientOptions(cl,'Всички клиенти')}</select></label></div><div class="actions">${btn('Нов запис','ops-new','plus','primary')}${btn('Калкулации','go','chart','secondary','data-page="calculations"')}${btn('Кошче и история','go','trash','secondary','data-page="dataSafety"')}</div></div>${rows.map(opsRow).join('')||empty()}`}
function opsNewPicker(){opsDialog('Какво да добавя?',`<div class="dashboard-grid">${Object.entries(OPS_KINDS).map(([k,d])=>btn(d.title,'ops-new-kind','plus','secondary',`data-kind="${k}"`)).join('')}</div>`)}
async function opsSaveRecord(form){const old=opsRows().find(r=>r.id===form.dataset.id),kind=form.dataset.kind,def=OPS_KINDS[kind],fd=new FormData(form),r={...old,id:old?.id||uid(),kind};for(const k of ['title','clientId','visitId','date','status','notes'])r[k]=String(fd.get(k)||'').trim();for(const [k,,t]of def.fields)r[k]=t==='number'?opsNumber(fd.get(k)):String(fd.get(k)||'').trim();if(fd.has('removePhoto'))delete r.photo;const photo=fd.get('photo');if(photo?.size)r.photo=await compressImage(photo,1200,.8);if(opsRows().some(x=>x.id!==r.id&&x.kind===r.kind&&x.clientId===r.clientId&&x.date===r.date&&x.title.trim().toLocaleLowerCase('bg')===r.title.toLocaleLowerCase('bg')))throw Error('Има запис със същото заглавие, вид, клиент и дата. Редактирай него или уточни различно заглавие.');if(change(()=>{const i=db.opsRecords.findIndex(x=>x.id===r.id);i<0?db.opsRecords.push(r):db.opsRecords[i]=r;})){wpCloseAfterSave();render();toast('Записът е запазен.')}}
function opsCalcLine(l={}){return `<div class="ops-calc-line" data-ops-line>${opsField('lineName','Материал / позиция',l.name)}${opsField('lineQty','Количество',l.qty??1,'number')}${opsField('lineUnit','Единица',l.unit||'бр.')}${opsField('lineCost','Себестойност за единица €',l.cost,'number')}<label><input type="checkbox" name="lineIncluded" ${l.included!==false?'checked':''}> Включи</label><label><input type="checkbox" name="lineOptional" ${l.optional?'checked':''}> Допълнителна опция</label>${btn('Премахни ред','ops-line-remove','trash','secondary')}</div>`}
function opsCalcEditor(id='',pref={}){const c=db.opsCalculations.find(c=>c.id===id)||{title:'Калкулация',date:today(),clientId:state.opsClient||'',status:'Чернова',margin:20,laborHours:null,laborRate:null,transport:null,rental:null,other:0,lines:[],...pref};opsDialog('Калкулация на обект',`<form id="ops-calc-form" data-id="${esc(id)}"><div class="form-grid">${opsField('title','Заглавие',c.title,'text',true)}<label class="field">Клиент<select name="clientId" required>${opsClientOptions(c.clientId)}</select></label>${opsField('date','Дата',c.date,'date',true)}${opsSelect('status','Състояние',c.status,['Чернова','Одобрена','Приключена'],true)}${opsField('margin','Целеви марж % от продажната цена',c.margin,'number',true)}</div><h3>Материали и позиции</h3><p class="muted">Цените са в EUR. Посочвай еднакви единици за количеството и единичната себестойност. Празна цена означава „неуточнена“.</p><div id="ops-calc-lines">${c.lines.map(opsCalcLine).join('')}</div>${btn('Добави позиция','ops-line-add','plus','secondary wide')}<h3>Други разходи</h3><div class="form-grid">${[['laborHours','Часове труд'],['laborRate','Себестойност на час €'],['transport','Транспорт общо €'],['rental','Наем общо €'],['other','Други разходи €']].map(([k,l])=>opsField(k,l,c[k],'number')).join('')}${opsField('notes','Вътрешни бележки',c.notes,'textarea')}</div><div id="ops-calc-preview" class="notice" aria-live="polite"></div><p>Марж 20% означава цена = себестойност ÷ 0,80. Допълнителните опции влизат само ако са отметнати „Включи“. Тази сметка не включва автоматично данъци и общи фирмени разходи.</p><div id="form-error" class="error" hidden></div><div class="actions"><button type="submit" class="primary">Запази</button>${id?btn('Към кошчето','ops-delete','trash','danger',`data-table="opsCalculations" data-id="${esc(id)}"`):''}</div></form>`);opsCalcPreview()}
function opsReadCalc(form){const fd=new FormData(form),lines=[...form.querySelectorAll('[data-ops-line]')].map(row=>({name:row.querySelector('[name=lineName]').value.trim(),qty:opsNumber(row.querySelector('[name=lineQty]').value,true),unit:row.querySelector('[name=lineUnit]').value.trim(),cost:opsNumber(row.querySelector('[name=lineCost]').value),included:row.querySelector('[name=lineIncluded]').checked,optional:row.querySelector('[name=lineOptional]').checked}));const r={title:String(fd.get('title')||'').trim(),clientId:String(fd.get('clientId')||''),date:String(fd.get('date')||''),status:String(fd.get('status')||''),margin:opsNumber(fd.get('margin'),true,99.99),notes:String(fd.get('notes')||'').trim(),lines};for(const k of ['laborHours','laborRate','transport','rental','other'])r[k]=opsNumber(fd.get(k));return r}
function opsCalcPreview(){const form=$('#ops-calc-form'),el=$('#ops-calc-preview');if(!form||!el)return;try{const a=opsCalc(opsReadCalc(form));el.textContent=(a.unknown?'НЕПЪЛНА СМЕТКА · ':'')+'Известна себестойност: '+money(a.cost)+' · Предложена цена: '+money(a.price)+' · Остатък: '+money(a.profit)}catch(e){el.textContent=e.message}}
function opsCalcRows(){return db.opsCalculations.filter(c=>!state.opsClient||c.clientId===state.opsClient).map(c=>{const a=opsCalc(c);return `<div class="card"><h3>${esc(c.title)}</h3><p>${esc(cname(c.clientId))} · ${date(c.date)} · ${esc(c.status)}</p>${a.unknown?'<p class="error">Има неуточнени разходи. Прехвърлянето към оферта е блокирано.</p>':''}<div class="total">Себестойност ${money(a.cost)}<strong>Предложена цена ${money(a.price)}</strong></div><p>Остатък преди общи разходи и данъци: ${money(a.profit)}</p><div class="actions">${btn('Редакция','ops-calc-edit','edit','secondary',`data-id="${esc(c.id)}"`)}${btn(c.documentId?'Отвори офертата':'Подготви оферта','ops-calc-quote','doc','secondary',`data-id="${esc(c.id)}"`)}${btn('Към покупки','ops-calc-buy','cart','secondary',`data-id="${esc(c.id)}"`)}</div></div>`}).join('')}
function opsCalculationsView(){return `<section class="card"><h2>Калкулации</h2><div class="actions">${btn('Нова калкулация','ops-calc-new','plus','primary')}${btn('Количества материали','ops-material','box','secondary')}</div><label class="field">Клиент<select id="ops-client">${opsClientOptions(state.opsClient||'','Всички клиенти')}</select></label><p>Офертата и покупките се създават след преглед. Калкулацията не отчита действителни разходи.</p></section>${opsCalcRows()||empty()}`}
function opsCalcPurchases(id){const c=db.opsCalculations.find(c=>c.id===id);if(!c)throw Error('Калкулацията липсва.');const rows=c.lines.map((l,i)=>({...l,index:i})).filter(l=>l.included&&!db.purchases.some(p=>p.opsCalculationId===id&&p.opsLineIndex===l.index));if(!rows.length)throw Error('Позициите вече са прехвърлени или няма включени материали.');return change(()=>{c.purchaseIds||=[];for(const l of rows){const p={id:uid(),name:l.name,clientId:c.clientId,date:today(),quantity:l.qty,unit:l.unit,amount:l.cost===null?0:cents(l.qty*l.cost)/100,opsUnpriced:l.cost===null,category:'Консумативи',supplier:'',done:false,priority:'Нормален',opsCalculationId:id,opsLineIndex:l.index,notes:l.cost===null?'Планова цена не е уточнена. Въведи преди отчитане на разход.':''};db.purchases.push(p);c.purchaseIds.push(p.id)}})}
function opsCalcQuote(id){const c=db.opsCalculations.find(c=>c.id===id);if(!c)throw Error('Калкулацията липсва.');if(c.documentId){const d=db.documents.find(d=>d.id===c.documentId);return previewDocument(d)}const a=opsCalc(c);if(a.unknown)throw Error('Попълни всички разходи, включително 0 за липсващите, преди офертата.');editor('documents','',{clientId:c.clientId,title:c.title,type:'Оферта',template:'Свободен документ',pricingMode:'lines',priceBasis:'once',discount:0,items:c.title.replace(/[|\r\n]/g,' ')+' | 1 | '+a.price,scope:c.lines.filter(l=>l.included).map(l=>`${l.name} — ${l.qty} ${l.unit}`).join('\n'),conditions:'Обхватът и цената подлежат на потвърждение. Допълнителните невключени позиции се възлагат отделно.'});$('#record-form').dataset.opsCalculation=id;}
function opsMaterialEditor(){opsDialog('Количества материали',`<form id="ops-material-form"><div class="form-grid">${opsField('area','Площ m²','','number',true)}${opsSelect('mode','Изчисление','layer',[['layer','Почва / пясък / мулч — дебелина cm → m³'],['rate','Семена / тор — норма g/m² → kg']],true)}${opsField('value','Дебелина cm или норма g/m²','','number',true)}${opsField('waste','Добавка за резерв %',0,'number',true)}</div><p>Нормата се въвежда по етикета или проекта. Обемът е геометричен; уплътняване и плътност не се предполагат.</p><button type="submit" class="primary">Изчисли</button><div id="ops-material-result" class="notice" aria-live="polite"></div><div id="form-error" class="error" hidden></div></form>`)}
function opsSafetyView(){return `<div class="card"><h2>Данни и възстановяване</h2><p>Изтритите записи се пазят с техните връзки и снимки. Възстановяването е общо за една операция и се проверява преди запис. Пълното нулиране от Настройки е отделно действие.</p><div class="actions">${btn('Изтегли архив','backup','download','primary')}${btn('Провери архив без възстановяване','ops-check-backup','check','secondary')}</div><input type="file" id="ops-check-file" accept=".json,application/json" hidden><div id="ops-check-result" role="status"></div></div><div class="card"><h3>Кошче</h3>${db.opsTrash.slice().reverse().map(t=>`<div class="list-row"><div class="grow"><strong>${date(t.date)} · ${t.items.length} записа</strong><small>${esc(t.items.slice(0,5).map(i=>opsLabel(i.table,i.record)).join(' · '))}</small></div>${btn('Възстанови','ops-restore','back','secondary',`data-id="${esc(t.id)}"`)}</div>`).join('')||empty('Кошчето е празно.')}</div><div class="card"><h3>Предишни версии на документи</h3><p>Преглед на запазените данни преди редакция. Не заменя текущия документ.</p>${db.opsVersions.slice().reverse().map(v=>btn(v.record.type+' № '+v.record.number+' · '+date(v.date),'ops-version','doc','secondary wide',`data-id="${esc(v.id)}"`)).join('')||empty()}</div><div class="card"><h3>Последни промени</h3>${db.opsHistory.slice(-50).reverse().map(h=>`<details><summary>${esc(new Date(h.time).toLocaleString('bg-BG'))}</summary><pre class="ops-pre">${esc(h.summary)}</pre></details>`).join('')||empty()}</div>`}
function opsGlobalResults(q){const needle=q.trim().toLocaleLowerCase('bg');if(needle.length<2)return empty('Въведи поне 2 знака.');const matches=[];for(const table of TABLES.filter(t=>!['opsTrash','opsHistory','opsVersions'].includes(t)))for(const r of db[table]){const hay=[r.title,r.name,r.description,r.service,r.notes,r.number,r.phone,r.address,r.model,r.brand,r.product].filter(x=>typeof x==='string').join(' ').toLocaleLowerCase('bg');if(hay.includes(needle)){matches.push({table,r});if(matches.length>=100)break}if(matches.length>=100)break}return matches.map(({table,r})=>`<button class="list-row" data-action="ops-search-open" data-table="${table}" data-id="${esc(r.id)}"><div class="grow"><strong>${esc(opsLabel(table,r))}</strong><small>${r.clientId?esc(cname(r.clientId)):''}</small></div>${icon('chevron')}</button>`).join('')||empty('Няма съвпадения.')}
function opsSearchView(){return `<div class="card"><h2>Търсене във всичко</h2><input type="search" id="ops-search" placeholder="Клиент, телефон, машина, бележка…" value="${esc(state.opsSearch||'')}" aria-label="Търсене във всички записи"><div id="ops-search-results">${opsGlobalResults(state.opsSearch||'')}</div></div>`}
function opsScheduleEditor(){const s=db.settings.opsSchedule||{anchor:today(),a:[0,0,0,0,0,8,8],b:[0,0,8,0,0,0,8],travel:.5,defaultHours:2};opsDialog('Свободно време и капацитет',`<form id="ops-schedule-form"><p>Посочи понеделника на седмица А. Редуването А/Б се повтаря през 14 дни. Това е твой график, не автоматично определени смени.</p>${opsField('anchor','Понеделник на седмица А',s.anchor,'date',true)}${['a','b'].map(w=>`<h3>Седмица ${w==='a'?'А':'Б'} · свободни часове</h3><div class="form-grid">${['Пон','Вт','Ср','Чет','Пет','Съб','Нед'].map((d,i)=>opsField(w+i,d,s[w][i],'number',true)).join('')}</div>`).join('')}<div class="form-grid">${opsField('travel','Планово време за път на посещение (часа)',s.travel,'number',true)}${opsField('defaultHours','Планова продължителност при липсващи часове',s.defaultHours,'number',true)}</div><div id="form-error" class="error" hidden></div><button type="submit" class="primary">Запази графика</button></form>`)}
function opsWorkloadView(){const w=opsWorkload(state.day);return `<div class="card"><h3>Капацитет за ${date(state.day)}</h3><p>Работа: ${w.work.toFixed(1)} ч. · Планов път: ${w.travel.toFixed(1)} ч. · Свободно време: ${w.capacity===null?'не е зададено':w.capacity+' ч.'}</p>${w.capacity!==null&&w.total>w.capacity?'<p class="error">Планът надхвърля свободното време.</p>':''}${w.unknown?'<p class="muted">За посещенията без часове е използвана плановата продължителност от настройките.</p>':''}<div class="actions">${btn('Свободни дни','ops-schedule','calendar','secondary')}${btn('Премести посещения','ops-reschedule','calendar','secondary')}</div></div>`}
function opsRescheduleEditor(){const rows=db.visits.filter(v=>v.date===state.day&&v.status==='Планирано');opsDialog('Преместване на посещения',`<form id="ops-reschedule-form"><p>Избери планираните посещения за ${date(state.day)}. Часовете се запазват. Свързаните огледи се обновяват; последващите грижи и наемите остават с уговорените си срокове.</p>${rows.map(v=>`<label class="wp-check"><input type="checkbox" name="visit" value="${esc(v.id)}"><span>${esc(cname(v.clientId))} · ${esc(v.time)} · ${esc(v.service)}</span></label>`).join('')||empty()}${opsField('target','Нова дата','','date',true)}<p>Прегледай свободното време и възможните застъпвания преди потвърждението.</p><div id="ops-reschedule-preview" class="notice"></div><div id="form-error" class="error" hidden></div><button type="submit" class="primary">Прегледай преместването</button></form>`)}
function opsFieldView(){const v=db.visits.find(v=>v.id===state.opsVisit),t=db.settings.opsTimer;if(!v)return `<div class="card"><h2>На обекта</h2>${db.visits.filter(v=>v.status!=='Отменено').sort(sortDate).reverse().slice(0,60).map(v=>btn(date(v.date)+' · '+cname(v.clientId)+' · '+v.service,'ops-field-open','visit','secondary wide',`data-id="${esc(v.id)}"`)).join('')||empty()}</div>`;const active=t?.visitId===v.id;return `<div class="card"><h2>${esc(cname(v.clientId))}</h2><p>${date(v.date)} · ${esc(v.time)} · ${esc(v.service)}</p><p>Записана работа: ${visitHours(v).toFixed(2)} ч.${active?'<br>Текущ таймер: '+(opsTimerElapsed(t)/3600000).toFixed(2)+' ч. · '+(t.started?'Работи':'Пауза'):''}</p><div class="actions">${btn(active&&t.started?'Пауза':'Започни / продължи','ops-timer','clock','primary',`data-id="${esc(v.id)}" data-mode="${active&&t.started?'pause':'start'}"`)}${active?btn('Запиши времето','ops-timer','check','secondary',`data-id="${esc(v.id)}" data-mode="finish"`)+btn('Отмени таймера','ops-timer','close','secondary',`data-id="${esc(v.id)}" data-mode="cancel"`):''}</div><p class="muted">Записването добавя измереното време веднъж към посещението. Статусът „Изпълнено“ се потвърждава отделно.</p><div class="actions">${btn('Снимки и посещение','edit','edit','secondary',`data-table="visits" data-id="${esc(v.id)}"`)}${btn('Вложени материали','ops-context-new','box','secondary',`data-kind="product" data-client="${esc(v.clientId)}" data-visit="${esc(v.id)}"`)}${btn('Нов проблем','ops-context-new','bell','secondary',`data-kind="issue" data-client="${esc(v.clientId)}" data-visit="${esc(v.id)}"`)}${btn('Разход','new','money','secondary',`data-table="expenses" data-client="${esc(v.clientId)}"`)}${btn('Отчет PDF','client-report','download','secondary',`data-id="${esc(v.id)}"`)}${btn('Работен лист за помощник','ops-helper','doc','secondary',`data-id="${esc(v.id)}"`)}${btn('Съобщение за клиента','ops-message','doc','secondary',`data-id="${esc(v.id)}"`)}</div></div>${opsRows().filter(r=>r.visitId===v.id).map(opsRow).join('')}`}
function opsHelperText(v){const p=wpPlans().find(p=>p.visitIds.includes(v.id));return ['РАБОТЕН ЛИСТ',cname(v.clientId),date(v.date)+' · '+v.time,v.service,p?'СТЪПКИ\n'+p.steps.map(s=>'□ '+s.text).join('\n'):'Уточни работните стъпки в плана.',p?'ЗА НАТОВАРВАНЕ\n'+p.packing.map(i=>'□ '+i.label).join('\n'):'','При проблем се свържи с отговорника.'].filter(Boolean).join('\n\n')}
function opsMessage(v){const c=client(v.clientId);opsDialog('Съобщение за клиента',`<label class="field">Шаблон<select id="ops-message-type"><option value="visit">Предстоящо посещение</option><option value="rain">Отлагане</option><option value="done">Приключена работа</option></select></label><label class="field">Текст за преглед<textarea id="ops-message-text" rows="7">${esc('Здравейте, планираното посещение за '+(c?.name||'Вашия обект')+' е на '+date(v.date)+' от '+v.time+'. Дейности: '+v.service+'. Моля, потвърдете достъпа до обекта.')}</textarea></label>${btn('Сподели текста','ops-message-share','doc','primary',`data-id="${esc(v.id)}"`)}<p class="muted">Прегледай текста. Изпращането се извършва от теб през избраното приложение.</p>`);$('#ops-message-type').onchange=e=>{$('#ops-message-text').value=e.target.value==='rain'?'Здравейте, поради неподходящи условия е необходимо да преместим посещението на '+date(v.date)+'. Ще съгласуваме нова дата.':e.target.value==='done'?'Здравейте, посещението на '+date(v.date)+' е приключено. Извършени дейности: '+v.service+'. Ще Ви изпратя отчета.':'Здравейте, планираното посещение е на '+date(v.date)+' от '+v.time+'. Дейности: '+v.service+'. Моля, потвърдете достъпа.'}}
function opsAlerts(){const dueRows=opsRows().filter(r=>r.due&&r.due<=today()&&!['Приключено','Отказано'].includes(r.status)),service=opsRows().filter(r=>r.kind==='maintenance'&&r.equipmentId&&r.meter!==null&&equipmentMeter(r.equipmentId)>=r.meter&&r.status!=='Приключено'),low=db.stockItems.filter(s=>stockBalance(s.id)<s.minQuantity),offers=db.documents.filter(d=>d.type==='Оферта'&&d.status==='Изпратена'&&(d.validUntil<today()||d.opFollowup&&d.opFollowup<=today()));return {dueRows,service,low,offers}}
function opsAlertHTML(){const a=opsAlerts();return `<div class="card"><h3>За внимание</h3><p>${a.dueRows.length} срока за действие · ${a.service.length} обслужвания по моточасове · ${a.low.length} ниски наличности · ${a.offers.length} оферти за проследяване</p>${a.dueRows.slice(0,8).map(r=>btn(r.title+' · '+date(r.due),'ops-edit','bell','secondary wide',`data-id="${esc(r.id)}"`)).join('')}${a.service.filter(r=>!a.dueRows.includes(r)).slice(0,5).map(r=>btn(r.title+' · моточасове','ops-edit','tool','secondary wide',`data-id="${esc(r.id)}"`)).join('')}${btn('Работен център','go','visit','secondary wide','data-page="operations"')}</div>`}
function opsHourlyHTML(){return `<div class="card"><h3>Резултат на час по клиент · ${esc(state.month)}</h3><p class="muted">Получени приходи минус отчетени разходи за обекта. Общите фирмени разходи и данъците не са разпределени. Времето за път е по записаните пътувания и техните дялове.</p>${db.clients.map(c=>{const vs=db.visits.filter(v=>v.clientId===c.id&&v.date.startsWith(state.month)&&v.status==='Изпълнено'),hours=vs.reduce((s,v)=>s+visitHours(v),0),travel=db.trips.filter(t=>t.date.startsWith(state.month)).reduce((s,t)=>s+(t.durationHours||0)*(t.shares.find(x=>x.clientId===c.id)?.weight||0)/100,0),income=sum(cashEntries().filter(p=>cashClient(p)===c.id&&p.date.startsWith(state.month)),p=>p.amount),cost=sum(clientExpenses(c.id).filter(e=>e.date.startsWith(state.month)),e=>e.amount),total=hours+travel;return `<p><strong>${esc(c.name)}</strong><br>${money(income-cost)} · работа ${hours.toFixed(1)} ч. + път ${travel.toFixed(1)} ч. · ${total>0?money((income-cost)/total)+'/ч.':'Няма въведени часове'}${vs.some(v=>!visitHours(v))?' · непълни часове':''}</p>`}).join('')}</div>`}
function opsSubscriptionHTML(){return `<div class="card"><h3>Посещения по абонамент · ${esc(state.month)}</h3>${db.subscriptions.filter(s=>s.start.slice(0,7)<=state.month&&s.end.slice(0,7)>=state.month).map(s=>{const vs=db.visits.filter(v=>v.subscriptionId===s.id&&v.date.startsWith(state.month)&&v.status!=='Отменено'),done=vs.filter(v=>v.status==='Изпълнено').length;return `<p><strong>${esc(cname(s.clientId))} · ${esc(s.name)}</strong><br>Договорени: ${s.frequency} · изпълнени: ${done} · планирани: ${vs.length-done} · оставащи за изпълнение: ${Math.max(0,s.frequency-done)}</p>`}).join('')||empty()}</div>`}
function opsClientSummary(id){const c=client(id);if(!c)throw Error('Клиентът липсва.');const visits=db.visits.filter(v=>v.clientId===id).sort(sortDate),upcoming=visits.filter(v=>v.status==='Планирано'&&v.date>=today()),done=visits.filter(v=>v.status==='Изпълнено').slice(-12);return '<!doctype html><html lang="bg"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GreenForce — отчет за обекта</title><style>body{font:16px system-ui;max-width:760px;margin:24px auto;padding:16px;color:#173d27}section{border:1px solid #d9e4db;border-radius:16px;padding:18px;margin:16px 0}pre{white-space:pre-wrap;font:inherit}</style><h1>GreenForce</h1><h2>'+esc(c.name)+'</h2><p>Справка към '+date(today())+'. Това е запазено копие, не се обновява автоматично.</p><section><h2>Предстоящи посещения</h2>'+upcoming.map(v=>'<p>'+date(v.date)+' · '+esc(v.time)+' · '+esc(v.service)+'</p>').join('')+'</section>'+done.map(v=>'<section><pre>'+esc(clientReportText(v))+'</pre></section>').join('')+'</html>'}
async function opsClick(e){const b=e.target.closest('[data-action^="ops-"]');if(!b)return;const id=b.dataset.id,mode=b.dataset.mode;try{switch(b.dataset.action){
case'ops-new':state.opsKind?opsForm(state.opsKind):opsNewPicker();break;
case'ops-new-kind':opsForm(b.dataset.kind);break;
case'ops-context-new':opsForm(b.dataset.kind,'',{clientId:b.dataset.client,visitId:b.dataset.visit||''});break;
case'ops-edit':{const r=opsRows().find(r=>r.id===id);if(r)opsForm(r.kind,id);break}
case'ops-delete':{const table=b.dataset.table;if(!['opsRecords','opsCalculations'].includes(table))throw Error('Невалиден вид запис.');confirmAction('Към кошчето','Записът ще бъде премахнат от активните данни. Може да се възстанови от Кошчето.',()=>{const ok=change(()=>{db[table]=db[table].filter(r=>r.id!==id);});if(ok)wpSetReturnFrame();return ok},true);break}
case'ops-restore':confirmAction('Възстановяване','Ще върна всички записи от тази операция, ако връзките им все още са валидни. Текущите записи няма да се презаписват.',()=>opsRestore(id));break;
case'ops-version':{const v=db.opsVersions.find(v=>v.id===id);opsDialog('Запазена версия на документ',`<p>${esc(v.record.type)} № ${esc(v.record.number)} · версия преди промяната на ${date(v.date)}</p><pre class="ops-pre">${esc(documentText(v.record))}</pre>${btn('PDF на тази версия','ops-version-pdf','download','secondary',`data-id="${esc(id)}"`)}`);break}
case'ops-version-pdf':{const v=db.opsVersions.find(v=>v.id===id);await exportDocumentPDF(v.record);break}
case'ops-task':{const r=opsRows().find(r=>r.id===id),existing=db.seasonalTasks.find(t=>t.opsSourceId===id||t.clientId===(r.clientId||'')&&t.title===r.title&&t.notes==='От Работен център: '+r.title);editor('seasonalTasks',existing?.id||'',{title:r.title,clientId:r.clientId||'',date:r.checkDate||r.due||today(),done:false,notes:'От Работен център: '+r.title});$('#manager-form').dataset.opsSource=id;break}
case'ops-pdf':{const r=opsRows().find(r=>r.id===id);await exportPDF(r.title,opsPublicText(r),'GreenForce-'+r.kind+'-'+r.date);break}
case'ops-calc-new':opsCalcEditor();break;case'ops-calc-edit':opsCalcEditor(id);break;
case'ops-line-add':if(document.querySelectorAll('[data-ops-line]').length>=100)throw Error('До 100 позиции.');$('#ops-calc-lines').insertAdjacentHTML('beforeend',opsCalcLine());opsCalcPreview();break;
case'ops-line-remove':b.closest('[data-ops-line]').remove();opsCalcPreview();break;
case'ops-calc-buy':{const c=db.opsCalculations.find(c=>c.id===id),rows=c.lines.filter(l=>l.included);confirmAction('Покупки от калкулацията',rows.map(l=>l.name+': '+l.qty+' '+l.unit+(l.cost===null?' · неуточнена цена':'')).join('\n')+'\nЩе се добавят само непрехвърлените позиции. Няма да се отчете финансов разход.',()=>opsCalcPurchases(id));break}
case'ops-calc-quote':opsCalcQuote(id);break;case'ops-material':opsMaterialEditor();break;
case'ops-check-backup':$('#ops-check-file').click();break;
case'ops-schedule':opsScheduleEditor();break;case'ops-reschedule':opsRescheduleEditor();break;
case'ops-field-open':state.page='fieldWork';state.opsVisit=id;if($('#modal')?.open){wpCloseAfterSave();render()}else go('fieldWork',{opsVisit:id});break;
case'ops-timer':if(['finish','cancel'].includes(mode))confirmAction(mode==='finish'?'Запис на работното време':'Отмяна на таймер',mode==='finish'?'Измереното време ще се добави веднъж към посещението.':'Текущото измерване ще се премахне. Записаните часове се запазват.',()=>opsTimer(mode,id));else if(opsTimer(mode,id))render();break;
case'ops-helper':{const v=db.visits.find(v=>v.id===id);await exportPDF('Работен лист',opsHelperText(v),'GreenForce-work-'+v.date);break}
case'ops-message':opsMessage(db.visits.find(v=>v.id===id));break;
case'ops-message-share':{const text=$('#ops-message-text').value;if(navigator.share)await navigator.share({title:'GreenForce',text});else{download(new Blob([text],{type:'text/plain;charset=utf-8'}),'GreenForce-message.txt');toast('Текстът е подготвен за споделяне.')}break}
case'ops-client-summary':{const html=opsClientSummary(id);download(new Blob([html],{type:'text/html;charset=utf-8'}),'GreenForce-client-summary.html');toast('Готово копие за клиента. Не включва вътрешните калкулации и бележки.');break}
case'ops-search-open':{const t=b.dataset.table,r=db[t].find(r=>r.id===id);if(!r)throw Error('Записът липсва.');if(t==='clients')go('client',{client:id});else if(t==='opsRecords')opsForm(r.kind,id);else if(t==='opsCalculations')opsCalcEditor(id);else if(t==='workPlans')go('workPlan',{wpPlan:id,wpTab:'Подготовка'});else if(t==='inspections')go('inspection',{inspection:id});else if(t==='landscapeProjects')go('landscapeProjects');else if(schemas[t]||MANAGER_TABLES.includes(t))editor(t,id);else{const p=menu.find(m=>m[0]===t);go(p?p[0]:'operations');toast('Записът е в '+(titles[t]||t));}break}
}}catch(err){if(err.name!=='AbortError')toast(err.message)}}
async function opsSubmit(e){const form=e.target;if(!form.id.startsWith('ops-'))return;e.preventDefault();const button=form.querySelector('[type=submit]');if(button?.disabled)return;if(button)button.disabled=true;try{switch(form.id){
case'ops-record-form':await opsSaveRecord(form);break;
case'ops-calc-form':{const old=db.opsCalculations.find(c=>c.id===form.dataset.id),r={...old,...opsReadCalc(form),id:old?.id||uid()};if(old?.purchaseIds?.length&&(r.clientId!==old.clientId||JSON.stringify(r.lines)!==JSON.stringify(old.lines)))throw Error('Материалите вече са прехвърлени към покупки. За променени количества направи нова калкулация, за да се запази историята.');if(old?.documentId)throw Error('Калкулацията е свързана със запазена оферта. Създай нова калкулация за нов вариант.');if(change(()=>{const i=db.opsCalculations.findIndex(c=>c.id===r.id);i<0?db.opsCalculations.push(r):db.opsCalculations[i]=r;})){wpCloseAfterSave();render()}break}
case'ops-material-form':{const fd=new FormData(form),mode=fd.get('mode');if(!['layer','rate'].includes(mode))throw Error('Избери вид изчисление.');const result=opsMaterial(fd.get('area'),mode,fd.get('value'),fd.get('waste'));$('#ops-material-result').textContent='Необходимо количество: '+result.toLocaleString('bg-BG',{maximumFractionDigits:3})+' '+(mode==='layer'?'m³':'kg');break}
case'ops-schedule-form':{const fd=new FormData(form),anchor=String(fd.get('anchor'));if(!opsDate(anchor,false)||new Date(anchor+'T12:00:00').getDay()!==1)throw Error('Избери понеделник за начало на седмица А.');const s={anchor,a:[],b:[],travel:opsNumber(fd.get('travel'),true,24),defaultHours:opsNumber(fd.get('defaultHours'),true,24)};for(const w of ['a','b'])s[w]=Array.from({length:7},(_,i)=>opsNumber(fd.get(w+i),true,24));if(change(()=>db.settings.opsSchedule=s)){wpCloseAfterSave();render()}break}
case'ops-reschedule-form':{const fd=new FormData(form),ids=fd.getAll('visit').map(String),target=String(fd.get('target'));if(!ids.length||!opsDate(target,false))throw Error('Избери посещения и нова дата.');const existing=opsWorkload(target),moving=db.visits.filter(v=>ids.includes(v.id)&&v.date!==target),extra=moving.reduce((a,v)=>a+(visitHours(v)||db.settings.opsSchedule?.defaultHours||0)+(db.settings.opsSchedule?.travel||0),0),over=existing.capacity!==null&&existing.total+extra>existing.capacity,same=db.visits.filter(v=>v.date===target&&!ids.includes(v.id)&&moving.some(m=>m.time===v.time)&&v.status!=='Отменено');const text=ids.map(id=>{const v=db.visits.find(v=>v.id===id);return cname(v.clientId)+' · '+date(v.date)+' → '+date(target)+' · '+v.time}).join('\n')+(over?'\nВНИМАНИЕ: планът надхвърля свободните часове.':'')+(same.length?'\nВНИМАНИЕ: има посещения със същия начален час.':'')+'\nПотвърди след преглед. Последващите проверки и сроковете за връщане не се местят.';confirmAction('Преглед на преместването',text,()=>opsReschedule(ids,target));break}
}}catch(err){errorForm(err.message)}finally{if(button)button.disabled=false}}
async function opsChange(e){const el=e.target;try{
if(el.id==='ops-kind'){state.opsKind=el.value;render()}if(el.id==='ops-client'){state.opsClient=el.value;render()}
if(el.closest('#ops-calc-form'))opsCalcPreview();
if(el.closest('#ops-record-form')&&el.name==='clientId'){const form=el.closest('form'),v=form.querySelector('[name=visitId]'),d=form.querySelector('[name=documentId]'),p=form.querySelector('[name=paymentId]');v.innerHTML='<option value="">Избери…</option>'+db.visits.filter(v=>v.clientId===el.value).map(v=>`<option value="${esc(v.id)}">${date(v.date)} · ${esc(v.service)}</option>`).join('');if(d)d.innerHTML='<option value="">Избери…</option>'+db.documents.filter(d=>d.clientId===el.value).map(d=>`<option value="${esc(d.id)}">${esc(d.type+' № '+d.number)}</option>`).join('');if(p)p.innerHTML='<option value="">Избери…</option>'+[...db.payments,...db.subscriptionPayments].filter(p=>opsPaidClient(p)===el.value).map(p=>`<option value="${esc(p.id)}">${date(p.date)} · ${money(p.amount)}</option>`).join('');}
if(el.id==='ops-check-file'&&el.files?.[0]){const f=el.files[0];if(f.size>200000000)throw Error('Архивът е твърде голям.');const raw=JSON.parse(await f.text()),restored=validate(structuredClone(raw)),refs=checkArchiveMedia(raw);$('#ops-check-result').textContent='Проверката премина: '+restored.clients.length+' клиенти, '+restored.visits.length+' посещения, '+new Set(refs).size+' медийни файла. Данните не са заменени. Това е проверка на формата и връзките; не е пробен запис на друго устройство.';el.value='';}
}catch(err){if(el.id==='ops-check-file'){$('#ops-check-result').textContent='Архивът не премина проверката: '+err.message;el.value='';}else toast(err.message)}}
function setupOperations(){
 titles.operations='Работен център';titles.calculations='Калкулации';titles.dataSafety='Кошче и история';titles.fieldWork='На обекта';titles.globalSearch='Търсене';
 views.operations=opsHub;views.calculations=opsCalculationsView;views.dataSafety=opsSafetyView;views.fieldWork=opsFieldView;views.globalSearch=opsSearchView;
 menu.push(['calculations','Калкулации','chart']);
 const home=views.home;views.home=()=>`<div class="card"><div class="actions">${btn('На обекта','go','visit','primary','data-page="fieldWork"')}${btn('Търсене','go','chevron','secondary','data-page="globalSearch"')}${btn('Работен център','go','box','secondary','data-page="operations"')}</div>${db.settings.opsTimer?'<p>Има неприключен таймер към посещение.</p>':''}</div>`+home()+opsAlertHTML();
 const settings=views.settings;views.settings=()=>settings()+`<div class="card"><h3>Защита и организация</h3>${btn('Кошче, история и проверка на архив','go','trash','secondary wide','data-page="dataSafety"')}${btn('Свободни дни и капацитет','ops-schedule','calendar','secondary wide')}</div>`;
 const cal=views.calendar;views.calendar=()=>cal()+opsWorkloadView();
 const notification=views.notifications;views.notifications=()=>notification()+opsAlertHTML();
 const reports=views.reports;views.reports=()=>reports()+opsHourlyHTML();
 const subs=views.subscriptions;views.subscriptions=()=>subs()+opsSubscriptionHTML();
 const clientV=views.client;views.client=()=>clientV()+`<div class="card"><h3>Организация на обекта</h3><div class="actions">${[['access','Достъп'],['issue','Проблем'],['extra','Допълнителна работа'],['acceptance','Приемане'],['warranty','Гаранция'],['map','Схема'],['renewal','Подновяване'],['idea','Сезонна идея']].map(([k,t])=>btn(t,'ops-context-new','plus','secondary',`data-kind="${k}" data-client="${esc(state.client)}"`)).join('')}${btn('Клиентска справка за споделяне','ops-client-summary','doc','secondary',`data-id="${esc(state.client)}"`)}</div></div>`+opsRows().filter(r=>r.clientId===state.client).map(opsRow).join('');
 for(const [page,kinds]of [['equipment',['maintenance','rental']],['finance',['stage']],['purchases',['supplier','return']],['documents',['extra']],['contracts',['renewal','warranty']],['supplies',['product','return']],['inspections',['lead']]]){const before=views[page];if(before)views[page]=()=>before()+`<div class="card"><h3>Допълнителни действия</h3><div class="actions">${kinds.map(k=>btn(OPS_KINDS[k].title,'ops-new-kind','plus','secondary',`data-kind="${k}"`)).join('')}${btn('Всички записи','go','visit','secondary','data-page="operations"')}</div></div>`;}
 const beforeDelete=managerBeforeDelete;managerBeforeDelete=(table,id)=>opsBeforeDelete(table,id)||beforeDelete(table,id);
 const ed=editor;editor=function(table,id='',pref={}){ed(table,id,pref);if(table==='visits'&&id&&$('#modal'))$('#modal').insertAdjacentHTML('beforeend',btn('На обекта — таймер и бързи действия','ops-field-open','visit','secondary wide',`data-id="${esc(id)}"`));};
 schemas.purchases.push(f('opsPriceConfirmed','Потвърдена действителна цена (включително 0 €)','checkbox'));
 const saved=wpRecordSaved;wpRecordSaved=function(table,r,form){saved(table,r,form);if(table==='documents'&&form.dataset.opsCalculation){const c=db.opsCalculations.find(c=>c.id===form.dataset.opsCalculation);if(!c||c.clientId!==r.clientId)throw Error('Калкулацията е за друг клиент.');c.documentId=r.id;}if(table==='purchases'&&r.opsUnpriced){if(r.amount>0||r.opsPriceConfirmed)delete r.opsUnpriced;}};
 const posted=purchaseExpense;purchaseExpense=function(id){if(db.purchases.find(p=>p.id===id)?.opsUnpriced)return toast('Първо въведи действителната цена на покупката.');return posted(id)};
 document.addEventListener('click',opsClick);document.addEventListener('submit',opsSubmit);document.addEventListener('change',opsChange);document.addEventListener('input',e=>{if(e.target.closest('#ops-calc-form'))opsCalcPreview();if(e.target.id==='ops-search'){state.opsSearch=e.target.value;$('#ops-search-results').innerHTML=opsGlobalResults(e.target.value)}});
 // Form source binding is applied inside the same transaction by managerSubmit.
}
